        "bg": "park",
        "loc": "公園",
        "loctime": "夜",
        "name": "",
        "text": "公園の夜は静かだった。三脚を立てるさくらの手つきは昼よりずっと慎重で、まるで何かを運ぶようだった。星は薄雲の向こうに、現像途中の像みたいに滲んでいた。町の人は皆、入学式も結婚式も、この写真館で撮った。店の壁は、町の家族の歴史そのものだった。雨の日、写真館の客足は止まる。そういう日は、古いネガの整理をするのが店の習わしだった。祖父の遺した手帳には、撮影料の記録の合間に、短い日記のような走り書きが残されていた。個展の案内状は、さくらが一枚ずつ手書きで宛名を書いた。印刷の文字では伝わらないものがある、と言って。星を撮る夜、公園のベンチには先客の忘れ物の手袋が置かれていた。持ち主は、もう現れなかった。藤堂は名刺の角を、指で何度も確かめる癖があった。正確な男の、唯一の落ち着かなさだった。店主のコーヒーは豆を二倍使う。苦さの向こうに、かすかな甘みがあると本人だけが信じていた。"
