        "name": "",
        "text": "翌日、藤堂が再び来た。今度は一人ではなかった。会場のギャラリーの支配人と一緒だった。さくらの個展が消えた理由が、そこで静かに形を持った。ミキの実家は隣町の現像所で、彼女の速口は、納期に追われる家業仕込みだと本人は胸を張った。夏の日の公園では、祖父がよく子供たちを集めて、無料で記念写真を撮っていたという。フィルムは光に弱く、熱に弱く、それでも人の記憶よりは長く、真実を抱えていられる。さくらが笑うと、店の空気が半段上がる。ミキはそれを、現像促進剤みたいなものだと言った。悠太が子供の頃に通った夏、写真館の暗室は、世界で一番静かで安全な場所だった。町の祭りの夜、写真館は臨時の撮影所になった。浴衣の家族が、代わる代わるレンズの前に立った。祖父と藤堂の父は、若い頃は釣り仲間だったという。その頃の写真だけが、なぜか一枚も残っていない。"
