        "loctime": "夜",
        "name": "",
        "text": "暗室の赤い灯の下、さくらと二人、缶を開けた。フィルムは静かにほどけていく。祖父の字で書かれた小さなメモが、缶の底から出てきた。『守るために、撮った』と。藤堂は名刺の角を、指で何度も確かめる癖があった。正確な男の、唯一の落ち着かなさだった。店主のコーヒーは豆を二倍使う。苦さの向こうに、かすかな甘みがあると本人だけが信じていた。ミキの実家は隣町の現像所で、彼女の速口は、納期に追われる家業仕込みだと本人は胸を張った。夏の日の公園では、祖父がよく子供たちを集めて、無料で記念写真を撮っていたという。フィルムは光に弱く、熱に弱く、それでも人の記憶よりは長く、真実を抱えていられる。さくらが笑うと、店の空気が半段上がる。ミキはそれを、現像促進剤みたいなものだと言った。悠太が子供の頃に通った夏、写真館の暗室は、世界で一番静かで安全な場所だった。",
        "label": "good01"
