        "id": "a214",
        "name": "",
        "text": "現像液の中で、像が浮かんできた。若い藤堂の父、泣く子供、そして子供を抱いて頭を下げる祖父。写真は不祥事の証拠ではなかった。隠して守った、保護の記録だった。町の祭りの夜、写真館は臨時の撮影所になった。浴衣の家族が、代わる代わるレンズの前に立った。祖父と藤堂の父は、若い頃は釣り仲間だったという。その頃の写真だけが、なぜか一枚も残っていない。写真は選ばれた瞬間だけを残す。選ばれなかった時間のほうが、本当は長い。さくらはそれを知っていた。閉店後の店内では、時計の秒針の音だけが聞こえる。さくらはその静けさが好きだと言った。展覧会の照明は、写真を昼とは違う顔に見せる。夜のギャラリーには、秘密めいた空気があった。町の時計台の鐘は、昔から五分だけ早く鳴る。誰も直そうとせず、それがこの町の標準時になっていた。"
