        "loctime": "翌週・雨の夜",
        "name": "",
        "text": "――一週間後。また雨の夜。相沢は来なかった。美咲は入口の見えるレジに立ち、自動ドアが鳴るたび、ほんの少しだけ肩を震わせていた。廃棄の時間になっても、彼女の目は入口から離れなかった。雨は先週より弱く、けれど長く続いていた。この街の梅雨は、まだ始まったばかりだった。美咲さんは雨の日のシフトを、一度も代わったことがない。それが『偶然』ではないことを、俺はもう知っていた。彼女の五年は、この入口と、この傘と、雨音の中で組み立てられていた。相沢の来ない雨の日は、これが初めてではなかった。この一週間、彼女は何度も入口を見て、何度も小さく肩を落としてきた。時計の針は、もう誰にも急かされていなかった。"
