        "text": "その夜、偽の婚約を披露する晩餐が開かれた。長テーブルの主賓席に俺とセレナ、向かいにアラン。ベルタは給仕だが存在感は主賓級だった。セレナの手が、テーブルの下で俺の袖を掴む。震えていた。演技ではなかった。俺はその手を、上からそっと押さえた。ベンチの木は古く、彼女の子どもの頃からここにあるのだという。恩師との思い出を話す時だけ、彼女の声は少し幼くなった。絵本の話をする彼女は幸せそうで、その幸せが恩師への思慕でできていることが、痛いほど伝わってきた。恩師の絵本の話は尽きなかった。日本の昔話、桃太郎や鶴の恩返し。彼女の日本語の原点は、愛情の記憶と結びついていた。思い出は、色褪せなかった。",
