        "name": "",
        "text": "翌日、グレゴリーが再び館を訪れた。今度はセレナも同席だった。グレゴリーは遺言書の写しを開き、静かに読み上げた。『セレナは一年間、日本人の家庭教師を雇い、教え、かつ教えられよ。その教師を審査し、相応しいと認めた時、書斎の鍵を渡せ』。俺は息を呑んだ。審査されていたのは、生徒ではなく俺だったのだ。アランは執事にコートを預ける仕草まで絵になった。だが俺が気になったのは彼の目だった。笑いながら、館のすべてを値踏みしていた。親族会という言葉が、初めて現実の圧力として俺の耳に届いた。彼女の結婚は、彼女だけの問題ではなかったのだ。アランの登場で、館の使用人たちの空気も変わった。婚約者候補という存在は、彼女の未来が他人の手で決められかねない現実の象徴だった。運命は、静かに動いていた。",
