        "id": "e171",
        "name": "",
        "text": "笑いが起きた。だが俺の中では、過去の授業が一斉に色を変えていた。拙いはずの発音、間違えたはずの慣用句、ノートの正確な用例、流暢な朗読。全部、俺を見るための目だったのだ。怒りよりも先に、認められたい、という気持ちが湧いてきた。庭の風が、彼女の髪を揺らした。頼みごとをする令嬢、という絵のはずが、俺の心臓だけがやけに騒がしかった。彼女の頼みは無茶だった。だが、その無茶を断れない理由が、俺の中に芽生え始めていた。彼女の頼みを聞いた瞬間、俺の中で教師としての線引きが音を立てて揺らいだ。断るべきだと頭は言い、心は別の返事を用意していた。心が、決まりかけていた。"
