        "text": "季節は巡り、契約満了まで一月を切った。親族会の圧力は強まっていた。満了日までにセレナが『相応しい相手』を示せなければ、館は親族会の管理下に入り、アランとの婚約が既定路線になる。偽の婚約は、嘘のままでは守り切れないところまで来ていた。晩餐の料理は豪華だったが、味はほとんど分からなかった。テーブルの下の彼女の指の震えが、俺の袖を通してずっと伝わってきたからだ。アランの視線が、俺と彼女の間を何度も往復した。試されているのは俺の演技力で、彼女の覚悟もまた試されていた。晩餐の席順にも親族会の意向が滲んでいた。だがセレナは俺の隣を譲らなかった。その小さな抵抗が、俺には何より嬉しかった。夜の静けさが、深まった。",
